SessionStart.command:
R="$(git rev-parse --show-toplevel)"; [ -f "$R/.loki/loki.json" ] || git -C "$R" cat-file -e HEAD:.loki/loki.json 2>/dev/null || [ -z "$(git -C "$R" rev-list -1 --all -- .loki/loki.json 2>/dev/null)" ] || { printf '%s
' 'loki: .loki/loki.json is not on this branch; Loki did not check this' >&2; printf '{}
'; exit 0; }; loki context --root "$R" --event SessionStart --host agy || { printf '%s
' 'loki: context unavailable' >&2; exit 2; }

hooks.command:
R="$(git rev-parse --show-toplevel)"; [ -f "$R/.loki/loki.json" ] || git -C "$R" cat-file -e HEAD:.loki/loki.json 2>/dev/null || [ -z "$(git -C "$R" rev-list -1 --all -- .loki/loki.json 2>/dev/null)" ] || { printf '%s
' 'loki: .loki/loki.json is not on this branch; Loki did not check this' >&2; printf '{"decision":"allow"}
'; exit 0; }; loki --root "$R" protect --harness agy || { printf '%s
' '{"decision":"deny","reason":"loki: hook command failed"}'; exit 0; }

R="$(git rev-parse --show-toplevel)"; [ -f "$R/.loki/loki.json" ] || git -C "$R" cat-file -e HEAD:.loki/loki.json 2>/dev/null || [ -z "$(git -C "$R" rev-list -1 --all -- .loki/loki.json 2>/dev/null)" ] || { printf '%s
' 'loki: .loki/loki.json is not on this branch; Loki did not check this' >&2; printf '{}
'; exit 0; }; loki --root "$R" hook --harness agy || { printf '%s
' 'loki: hook command failed' >&2; printf '{}
'; exit 0; }
